public class SafeClusterHandle : SafeHandle
{
    public override bool IsInvalid => this.handle == IntPtr.Zero;

    public static SafeClusterHandle OpenClusterHandle(
        string clusterName,
        ClusterAccessRights desiredAccess,
        out ClusterAccessRights grantedAccess)
    {
        var clusterHandle = ClusterApi.OpenClusterEx(clusterName, desiredAccess, out grantedAccess);
        if (clusterHandle == IntPtr.Zero)
        {
            var error = Marshal.GetLastWin32Error();
            throw new Win32Exception(error);  // Line 56 - CRITICAL ERROR POINT
        }
        return new SafeClusterHandle(clusterHandle);
    }

    protected override bool ReleaseHandle()
    {
        if (this.finalized == false) return false;
        this.finalized = true;
        var clusterHandle = Interlocked.Exchange(ref this.handle, IntPtr.Zero);
        if (clusterHandle != IntPtr.Zero)
        {
            return ClusterApi.CloseCluster(clusterHandle);
        }
        return true;
    }
}
```

