private async Task WriteFileAtomicAsync(string filePath, byte[] data, CancellationToken token)
{
    var tempFile = filePath + ".tmp." + Guid.NewGuid().ToString("N");

    using (var fs = new FileStream(
        tempFile,
        FileMode.Create,
        FileAccess.Write,
        FileShare.None,      // Exclusive write access
        bufferSize: 4096,
        useAsync: true))
    {
        await fs.WriteAsync(data, 0, data.Length, token).ConfigureAwait(false);
